SENSES_BBOX = (15.4, 24.6, 183.6, 176.8)

def g_sense(h=10.2, thicken=5.0):
    """the senses testify: ear, eye, nose, mouth (מוחשות)"""
    bx0, by0, bx1, by1 = SENSES_BBOX
    k = h / (by1 - by0); w = (bx1 - bx0) * k
    cx, cy = 0.0, CY + 0.2
    return (f'<g transform="translate({cx - w/2:.3f} {cy - h/2:.3f}) scale({k:.5f}) translate({-bx0:.2f} {-by0:.2f})" '
            f'fill="{W}" stroke="{W}" stroke-width="{thicken}" stroke-linejoin="round" stroke-linecap="round">{SENSES_BODY}</g>')

def g_common():
    """a crowd: three heads and shoulders"""
    out = ""
    for x in (-4.8, 0, 4.8):
        out += (f'<circle cx="{x}" cy="{CY-2.0}" r="1.55" fill="{W}"/>\n  '
                f'<path d="M {x-2.5:.2f} {CY+3.4} Q {x-2.5:.2f} {CY+0.2} {x:.2f} {CY+0.2} Q {x+2.5:.2f} {CY+0.2} {x+2.5:.2f} {CY+3.4} Z" fill="{W}"/>\n  ')
    return out

