def g_tradition(w=13.6, rot=-16):
    """handed down: two hands reaching for each other, fingertips almost touching (מסורה).
    Rotated a little towards the horizontal so the pair fills the plinth."""
    k = w / 1280.0; h = 1056.0 * k
    cx, cy = 0.0, CY
    inner = "".join(f'<path d="{d}"/>' for d in HANDS_PATHS)
    return (f'<g transform="translate({cx:.3f} {cy:.3f}) rotate({rot}) translate({-w/2:.3f} {-h/2:.3f}) scale({k:.6f})">'
            f'<g transform="translate(0,1056) scale(0.1,-0.1)" fill="{W}" stroke="none">{inner}</g></g>')

def g_deduction():
    """an arrow: it follows"""
    return (f'<path d="M -5.2 {CY} H 3.2" {st(W, 1.7)}/>\n  '
            f'<path d="M 1.4 {CY-3.0} L 4.8 {CY} L 1.4 {CY+3.0}" {st(W, 1.7)}/>')

# axiom: self-evident, "clear as the sun" (ברור כשמש); Ramchal's own example is "two is more than one",
# but a 1<2 glyph reads as a comparison of weight at 20 px, so the sun carries it.
icon("ground-axiom", "the mind dictates it, no training needed (מושכלות ראשונים)", plinth(M, "axiom") + "\n  " + inlay(g_axiom_sun(), CY), M)
icon("ground-sense", "the senses testify to it (מוחשות)", plinth(M, "sense") + "\n  " + inlay(g_sense(), CY), M)
icon("ground-common-sense", "what most people hold by nature (מפורסמות)", plinth(M, "common") + "\n  " + inlay(g_common(), CY), M)
icon("ground-tradition", "handed down: a verse, a halacha, an undisputed authority (מקובלות)", plinth(M, "tradition") + "\n  " + inlay(g_tradition(), CY), M)
icon("ground-deduction", "it follows from a true premise by a deduction (הקש); the chapter 7 badge says which", plinth(M, "deduction") + "\n  " + inlay(g_deduction(), CY), M)

